        uint256 treeId = self.treeId;
        if (treeId == 0) {
            revert NotInitialized();
        }
        emit IIMTEvents.RepeatedLeafs(treeId, startIndex, nextIndex, value);
        emit IIMTEvents.NewRoot(treeId, newRoot, nextIndex);
        return (newRoot, startIndex, nextIndex);
